1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Console\Commands;
6	
7	use App\Models\Category1;
8	use App\Support\XlsxFillColorReader;
9	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
10	use AtrioTeam\DigitalHub\Tags\Models\Tag;
11	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
12	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
13	use Illuminate\Console\Command;
14	use Illuminate\Support\Collection;
15	use Illuminate\Support\Facades\DB;
16	use OpenSpout\Reader\XLSX\Options;
17	use OpenSpout\Reader\XLSX\Reader;
18	
19	/**
20	 * Import dei tag anagrafica dei tessuti da
21	 * `import/2026-07-21/Tessuti interior e outdoor - filtri.xlsx`, un foglio per
22	 * destinazione (`Interior`, `Outdoor`).
23	 *
24	 * Il foglio è a colonna singola: righe intestazione di blocco seguite dai
25	 * valori, separatori (`____`) e righe vuote ignorati. Ogni blocco diventa una
26	 * TagCategory dentro il gruppo tessuti della sua destinazione (entity_type=
27	 * fabric, target=entity), ogni valore un Tag. La colonna B porta lo swatch dei
28	 * colori, letto da {@see XlsxFillColorReader} e salvato sul tag.
29	 *
30	 * La colonna D "tipo dato" dichiara quali blocchi sono davvero tag: gli altri
31	 * sono proprietà del `Fabric` (colonne della tabella, popolate da
32	 * `app:import-fabrics`) e non devono diventare TagCategory.
33	 *
34	 * **Il file fa fede**: i nomi vengono riallineati (il casing cambia fra una
35	 * revisione e l'altra) e i valori caduti dal file rimossi — tranne quelli
36	 * ancora assegnati a un tessuto, che `app:import-fabrics` può aver aggiunto
37	 * perché i dati li usano ma la mappatura non li elenca (es. il pattern
38	 * "Armatura"). Cancellarli qui vorrebbe dire toglierli e rimetterli a ogni giro.
39	 *
40	 * ⚠️ **Outdoor non è ancora implementato**: il foglio esiste nel file ma i suoi
41	 * blocchi sono in attesa di conferma dal cliente, e il foglio OUTDOOR del file
42	 * dati non ha comunque colonne tag da cui assegnarli. Viene riconosciuto e
43	 * saltato con un avviso.
44	 */
45	class ImportFiltriTessuti extends Command
46	{
47	    protected $signature = 'app:import-filtri-tessuti '
48	        . '{--file=storage/app/private/import/2026-07-21/Tessuti interior e outdoor - filtri.xlsx} '
49	        . '{--fresh : Svuota i tag delle categorie interessate prima di reimportare}';
50	
51	    protected $description = 'Import dei tag anagrafica tessuti (Interior/Outdoor) dal file filtri';
52	
53	    private const SHEET_INTERIOR = 'Interior';
54	
55	    private const SHEET_OUTDOOR = 'Outdoor';
56	
57	    /** Colonna con lo sfondo colorato accanto ai valori del blocco "Colori". */
58	    private const COLOR_COLUMN = 'B';
59	
60	    /**
61	     * Blocchi dichiarati TAG → slug stabile e nome della TagCategory.
62	     *
63	     * @var array<string, array{slug: string, name: string}>
64	     */
65	    private const BLOCKS = [
66	        'tipologia' => ['slug' => 'tipologia', 'name' => 'Tipologia'],
67	        'colori' => ['slug' => 'colori', 'name' => 'Colori'],
68	        'pattern' => ['slug' => 'pattern', 'name' => 'Pattern'],
69	    ];
70	
71	    /**
72	     * Blocchi dichiarati PROPRIETÀ: sono colonne di `fabrics`, non tag. Vanno
73	     * comunque riconosciuti come intestazioni, altrimenti i loro valori
74	     * finirebbero nel blocco tag precedente.
75	     *
76	     * @var list<string>
77	     */
78	    private const PROPERTY_BLOCKS = ['proprietà', 'costo', 'moodboard', 'categoria'];
79	
80	    /**
81	     * TagCategory create dalle versioni precedenti del file e non più previste:
82	     * "Tipo disegno" è stato rinominato "Pattern", gli altri tre blocchi sono
83	     * diventati proprietà.
84	     *
85	     * @var list<string>
86	     */
87	    private const OBSOLETE_CATEGORIES = ['tipo-disegno', 'proprieta', 'categoria', 'moodboard'];
88	
89	    public function handle(): int
90	    {
91	        $file = (string) $this->option('file');
92	        if (! is_file($file)) {
93	            $this->error("File non trovato: {$file}");
94	
95	            return self::FAILURE;
96	        }
97	
98	        if (in_array(self::SHEET_OUTDOOR, $this->sheetNames($file), true)) {
99	            $this->warn('Foglio "' . self::SHEET_OUTDOOR . '" ignorato: i filtri Outdoor sono in attesa di conferma.');
100	        }
101	
102	        $blocks = $this->parseSheet($file, self::SHEET_INTERIOR);
103	        if ($blocks === null) {
104	            $this->error('Foglio "' . self::SHEET_INTERIOR . '" non trovato nel file.');
105	
106	            return self::FAILURE;
107	        }
108	
109	        // la destinazione è un presupposto della tassonomia, non un dato da
110	        // importare: se manca la si crea, così il comando non dipende da un
111	        // seeder lanciato prima
112	        $indoor = Category1::query()->firstOrCreate(
113	            ['slug' => 'indoor'],
114	            ['name' => ['it' => 'Interior', 'en' => 'Interior']],
115	        );
116	
117	        $stats = ['categories' => 0, 'tags' => 0, 'swatches' => 0, 'obsolete' => 0, 'pruned' => 0];
118	
119	        DB::transaction(function () use ($indoor, $blocks, &$stats): void {
120	            $group = $this->resolveGroup($indoor);
121	
122	            $stats['obsolete'] = $this->dropObsoleteCategories($group);
123	
124	            $names = array_column(self::BLOCKS, 'name', 'slug');
125	
126	            $categorySort = 0;
127	            foreach ($blocks as $slug => $values) {
128	                $name = $names[$slug];
129	                $category = TagCategory::query()->updateOrCreate(
130	                    ['tag_group_id' => $group->id, 'slug' => $slug],
131	                    ['name' => ['it' => $name, 'en' => $name], 'sort' => $categorySort++],
132	                );
133	                $stats['categories']++;
134	
135	                if ($this->option('fresh')) {
136	                    Tag::query()->where('tag_category_id', $category->id)->delete();
137	                }
138	
139	                $existing = Tag::query()->where('tag_category_id', $category->id)->get();
140	                $kept = [];
141	
142	                foreach ($values as ['value' => $value, 'color' => $color]) {
143	                    $key = $this->normalize($value);
144	
145	                    // il file cambia il casing fra una revisione e l'altra
146	                    // ("arancioni e terracotta" → "Arancioni e terracotta"):
147	                    // un match esatto creerebbe un doppione invece di rinominare
148	                    $tag = $existing->first(
149	                        fn (Tag $t): bool => $this->normalize($t->name) === $key,
150	                    ) ?? new Tag();
151	
152	                    $tag->tag_category_id = $category->id;
153	                    $tag->setTranslations('name', ['it' => $value, 'en' => $value]);
154	                    $tag->color = $color;
155	                    $tag->save();
156	                    $kept[] = $tag->id;
157	                    $stats['tags']++;
158	                    if ($color !== null) {
159	                        $stats['swatches']++;
160	                    }
161	                }
162	
163	                $stats['pruned'] += $this->pruneTags($existing, $kept);
164	            }
165	        });
166	
167	        $this->info('Import tag tessuti completato.');
168	        $this->table(
169	            ['Metrica', 'Valore'],
170	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
171	        );
172	
173	        return self::SUCCESS;
174	    }
175	
176	    /**
177	     * Elimina i tag caduti dal file (e i doppioni di casing lasciati dalle
178	     * revisioni precedenti), risparmiando quelli ancora assegnati a un tessuto.
179	     *
180	     * @param Collection<int, Tag> $existing
181	     * @param list<int> $kept
182	     */
183	    private function pruneTags(Collection $existing, array $kept): int
184	    {
185	        $dropped = $existing->reject(fn (Tag $tag): bool => in_array($tag->id, $kept, true));
186	        if ($dropped->isEmpty()) {
187	            return 0;
188	        }
189	
190	        $inUse = DB::table('taggables')
191	            ->whereIn('tag_id', $dropped->pluck('id'))
192	            ->distinct()
193	            ->pluck('tag_id')
194	            ->all();
195	
196	        $stale = $dropped->reject(fn (Tag $tag): bool => in_array($tag->id, $inUse, true));
197	        if ($stale->isEmpty()) {
198	            return 0;
199	        }
200	
201	        Tag::query()->whereIn('id', $stale->pluck('id'))->delete();
202	
203	        return $stale->count();
204	    }
205	
206	    /**
207	     * Elimina le TagCategory non più previste dal file, con i loro tag (e
208	     * quindi le associazioni, via cascade sul pivot).
209	     */
210	    private function dropObsoleteCategories(TagGroup $group): int
211	    {
212	        $obsolete = TagCategory::query()
213	            ->where('tag_group_id', $group->id)
214	            ->whereIn('slug', self::OBSOLETE_CATEGORIES)
215	            ->pluck('id');
216	
217	        if ($obsolete->isEmpty()) {
218	            return 0;
219	        }
220	
221	        Tag::query()->whereIn('tag_category_id', $obsolete)->delete();
222	        TagCategory::query()->whereIn('id', $obsolete)->delete();
223	
224	        return $obsolete->count();
225	    }
226	
227	    /**
228	     * Blocchi del foglio, con l'eventuale swatch della riga.
229	     * Ritorna null se il foglio non esiste.
230	     *
231	     * @return array<string, list<array{value: string, color: string|null}>>|null
232	     */
233	    private function parseSheet(string $file, string $sheetName): ?array
234	    {
235	        $blocks = null;
236	        $current = null;
237	        // dentro un blocco PROPRIETÀ: i valori vanno scartati in silenzio
238	        $skipping = false;
239	
240	        $rowColors = (new XlsxFillColorReader())->read($file, $sheetName, self::COLOR_COLUMN);
241	
242	        // preserva le righe vuote così l'indice del RowIterator coincide con
243	        // il numero di riga reale del foglio (chiave di $rowColors)
244	        $options = new Options();
245	        $options->SHOULD_PRESERVE_EMPTY_ROWS = true;
246	
247	        $reader = new Reader($options);
248	        $reader->open($file);
249	        foreach ($reader->getSheetIterator() as $sheet) {
250	            if ($sheet->getName() !== $sheetName) {
251	                continue;
252	            }
253	            $blocks = [];
254	
255	            /** @var int $rowNumber */
256	            foreach ($sheet->getRowIterator() as $rowNumber => $row) {
257	                $raw = ($row->getCells()[0] ?? null)?->getValue();
258	                $value = is_scalar($raw) ? trim((string) $raw) : '';
259	                if ($value === '' || preg_match('/^_+$/', $value) === 1) {
260	                    continue;
261	                }
262	
263	                $normalized = $this->normalize($value);
264	
265	                $block = self::BLOCKS[$normalized] ?? null;
266	                if ($block !== null) {
267	                    $current = $block['slug'];
268	                    $skipping = false;
269	                    $blocks[$current] ??= [];
270	
271	                    continue;
272	                }
273	
274	                if (in_array($normalized, self::PROPERTY_BLOCKS, true)) {
275	                    $current = null;
276	                    $skipping = true;
277	
278	                    continue;
279	                }
280	
281	                if ($skipping) {
282	                    continue;
283	                }
284	
285	                if ($current === null) {
286	                    $this->warn("Valore fuori da ogni blocco, ignorato: {$value}");
287	
288	                    continue;
289	                }
290	
291	                $blocks[$current][] = ['value' => $value, 'color' => $rowColors[$rowNumber] ?? null];
292	            }
293	
294	            break;
295	        }
296	        $reader->close();
297	
298	        return $blocks;
299	    }
300	
301	    /** @return list<string> */
302	    private function sheetNames(string $file): array
303	    {
304	        $names = [];
305	        $reader = new Reader();
306	        $reader->open($file);
307	        foreach ($reader->getSheetIterator() as $sheet) {
308	            $names[] = $sheet->getName();
309	        }
310	        $reader->close();
311	
312	        return $names;
313	    }
314	
315	    /** Gruppo tag anagrafica dei tessuti Interior (creato se assente). */
316	    private function resolveGroup(Category1 $indoor): TagGroup
317	    {
318	        return TagGroup::query()
319	            ->where('entity_type', 'fabric')
320	            ->where('target', TagTarget::Entity)
321	            ->where('category_1_id', $indoor->id)
322	            ->first()
323	            ?? TagGroup::query()->create([
324	                'entity_type' => 'fabric',
325	                'target' => TagTarget::Entity,
326	                'category_1_id' => $indoor->id,
327	                'name' => ['it' => 'Filtri Tessuti Interior', 'en' => 'Interior fabric filters'],
328	            ]);
329	    }
330	
331	    private function normalize(string $value): string
332	    {
333	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
334	    }
335	}
336

