1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Fabrics;
6	
7	use App\Models\Category1;
8	use App\Models\Fabric;
9	use App\Models\FabricCategory;
10	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
11	use AtrioTeam\DigitalHub\Tags\Models\Tag;
12	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
13	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
14	use Illuminate\Foundation\Testing\RefreshDatabase;
15	use OpenSpout\Common\Entity\Row;
16	use OpenSpout\Writer\XLSX\Options;
17	use OpenSpout\Writer\XLSX\Writer;
18	use Tests\TestCase;
19	
20	/**
21	 * Assegnazione dei tag ai colori tessuto da parte di `app:import-fabrics`.
22	 * Le tre colonne tag del foglio INTERIOR (Tipologia, Pattern, Colore) sono
23	 * liste separate da virgola risolte sull'anagrafica per nome normalizzato:
24	 * i valori sconosciuti non creano tag al volo.
25	 */
26	class ImportFabricsTagsTest extends TestCase
27	{
28	    use RefreshDatabase;
29	
30	    private string $file;
31	
32	    private string $filtriFile;
33	
34	    protected function setUp(): void
35	    {
36	        parent::setUp();
37	
38	        $this->file = tempnam(sys_get_temp_dir(), 'tessuti') . '.xlsx';
39	        $this->filtriFile = tempnam(sys_get_temp_dir(), 'filtri') . '.xlsx';
40	    }
41	
42	    protected function tearDown(): void
43	    {
44	        foreach ([$this->file, $this->filtriFile] as $file) {
45	            if (is_file($file)) {
46	                unlink($file);
47	            }
48	        }
49	
50	        parent::tearDown();
51	    }
52	
53	    /**
54	     * Foglio "Interior" del file filtri tessuti: colonna singola con le
55	     * intestazioni di blocco seguite dai valori. Senza swatch in colonna B —
56	     * qui interessa quali tag sopravvivono al rilancio, non i colori.
57	     */
58	    private function writeFiltriSheet(): void
59	    {
60	        $writer = new Writer(new Options());
61	        $writer->openToFile($this->filtriFile);
62	        $writer->getCurrentSheet()->setName('Interior');
63	
64	        $rows = ['Tipologia', 'Jaquard', 'Shine', 'Colori', 'Oro', 'Pattern', 'Geometrico'];
65	        foreach ($rows as $row) {
66	            $writer->addRow(Row::fromValues([$row]));
67	        }
68	
69	        $writer->close();
70	    }
71	
72	    /**
73	     * Anagrafica minima: la tassonomia attesa da CATEGORY_MAP più le tre
74	     * TagCategory su cui l'import risolve le colonne tag.
75	     */
76	    private function seedTaxonomy(): void
77	    {
78	        $indoor = Category1::create(['name' => ['it' => 'Indoor'], 'slug' => 'indoor']);
79	
80	        FabricCategory::create([
81	            'name' => ['it' => 'Tessuti Luxury'],
82	            'slug' => 'luxury-fabrics',
83	            'category_1_id' => $indoor->id,
84	        ]);
85	
86	        $group = TagGroup::create([
87	            'entity_type' => 'fabric',
88	            'target' => TagTarget::Entity,
89	            'category_1_id' => $indoor->id,
90	            'name' => ['it' => 'Filtri Tessuti Interior'],
91	        ]);
92	
93	        $tags = [
94	            'tipologia' => ['Jaquard', 'Shine'],
95	            'pattern' => ['Disegno grande', 'Geometrico'],
96	            'colori' => ['Oro', 'Sabbia Beige e Neutri'],
97	        ];
98	
99	        foreach ($tags as $slug => $names) {
100	            $category = TagCategory::create([
101	                'tag_group_id' => $group->id,
102	                'slug' => $slug,
103	                'name' => ['it' => ucfirst($slug)],
104	            ]);
105	
106	            foreach ($names as $name) {
107	                Tag::create(['tag_category_id' => $category->id, 'name' => ['it' => $name]]);
108	            }
109	        }
110	    }
111	
112	    /**
113	     * Scrive un foglio INTERIOR con il tracciato a 22 colonne: intestazione più
114	     * le righe passate, ognuna già nell'ordine delle colonne.
115	     *
116	     * @param list<list<string>> $rows
117	     */
118	    private function writeSheet(array $rows): void
119	    {
120	        $writer = new Writer(new Options());
121	        $writer->openToFile($this->file);
122	        $writer->getCurrentSheet()->setName('INTERIOR');
123	
