 * devono sparire anche qui. Ritorna true se almeno un tag è stato associato.
 *
 * @param list<mixed> $cells
 * @param array<string, int> $cols
 */
private function syncTags(Fabric $fabric, array $cells, array $cols, bool $outdoor): bool
{
    $destination = $outdoor ? 'outdoor' : 'indoor';
    $tagColumns = $outdoor ? self::TAG_COLUMNS_OUTDOOR : self::TAG_COLUMNS_INTERIOR;
    $ids = [];

    foreach ($tagColumns as $column => $categorySlug) {
        $raw = $this->s($cells[$cols[$column]] ?? null);
        if ($raw === '') {
            continue;
        }

        foreach (explode(',', $raw) as $value) {
            $normalized = $this->normalize($value);
            if ($normalized === '') {
                continue;
            }

            // valore usato dai dati ma assente dalla mappatura filtri:
            // entra in anagrafica invece di essere scartato
            $id = $this->tagIndex[$destination][$categorySlug][$normalized]
                ?? $this->createTag($destination, $categorySlug, trim($value));

            if ($id !== null) {
                $ids[] = $id;
            }
        }
    }

    $fabric->tags()->sync($ids);

    return $ids !== [];
}

