    /**
     * Dal 27 luglio 2026 anche OUTDOOR porta tag (Pattern e Colore, colonne
     * F/G): risolti sul gruppo tag della destinazione Outdoor, distinto da
     * quello Interior anche se gli slug delle TagCategory coincidono.
     */
    public function test_it_assigns_tags_from_the_two_outdoor_columns(): void
    {
        $this->seedOutdoorTaxonomy();
        $this->writeOutdoorSheet([
            $this->outdoorRow('CA019', 'Uniti', 'Sabbia beige e Naturali'),
        ]);

        $this->import();

        $tags = Fabric::where('code', 'CA019')->firstOrFail()->tags->pluck('name');

        $this->assertEqualsCanonicalizing(['Uniti', 'Sabbia beige e Naturali'], $tags->all());
    }

    public function test_outdoor_and_interior_tags_do_not_leak_across_destinations(): void
    {
        $this->seedTaxonomy();
        $this->seedOutdoorTaxonomy();

        $this->writeSheet([$this->row('CAMD01', 'Jaquard', '', '')]);
        $this->import();

        $this->writeOutdoorSheet([$this->outdoorRow('CA019', 'Uniti', '')]);
        $this->import();

