use Illuminate\Support\Facades\Schema;

/**
 * Sposta l'associazione prodotto↔tessuto dal livello FabricCategory (tipologia)
 * al livello Fabric (singolo colore): la nuova `fabric_product` sostituisce
 * `fabric_category_product`. I dati esistenti vengono migrati collegando ogni
 * prodotto a tutti i Fabric della FabricCategory a cui era associato.
 */
return new class () extends Migration {
    public function up(): void
    {
        Schema::create('fabric_product', function (Blueprint $table) {
            $table->foreignId('fabric_id')->constrained('fabrics')->cascadeOnDelete();
            $table->foreignId('product_id')->constrained('products')->cascadeOnDelete();
            $table->primary(['fabric_id', 'product_id']);
        });

        DB::statement('
            INSERT IGNORE INTO fabric_product (fabric_id, product_id)
            SELECT fabrics.id, fabric_category_product.product_id
            FROM fabric_category_product
            INNER JOIN fabrics ON fabrics.fabric_category_id = fabric_category_product.fabric_category_id
        ');

        Schema::dropIfExists('fabric_category_product');
    }

    public function down(): void
    {
        Schema::create('fabric_category_product', function (Blueprint $table) {
            $table->foreignId('fabric_category_id')->constrained('fabric_categories')->cascadeOnDelete();
            $table->foreignId('product_id')->constrained('products')->cascadeOnDelete();
            $table->primary(['fabric_category_id', 'product_id']);
        });

        DB::statement('
            INSERT IGNORE INTO fabric_category_product (fabric_category_id, product_id)
            SELECT DISTINCT fabrics.fabric_category_id, fabric_product.product_id
            FROM fabric_product
            INNER JOIN fabrics ON fabrics.id = fabric_product.fabric_id
            WHERE fabrics.fabric_category_id IS NOT NULL
        ');

        Schema::dropIfExists('fabric_product');
    }
};

